import React, { useState } from "react";
import Navbar from "../components/Navbar";
import { api } from "../utils/api";

export default function Report() {
  const [loading, setLoading] = useState(false);
  const [ticketId, setTicketId] = useState("");

  const [form, setForm] = useState({
    fullName: "",
    phone: "",
    category: "WHATSAPP",
    message: "",
    link: "",
    upiId: "",
    suspectNumber: ""
  });

  const [screenshot, setScreenshot] = useState(null);

  async function submit(e) {
    e.preventDefault();
    setLoading(true);
    setTicketId("");

    try {
      const fd = new FormData();
      Object.keys(form).forEach((k) => fd.append(k, form[k]));
      if (screenshot) fd.append("screenshot", screenshot);

      const res = await api.post("/api/cases", fd, {
        headers: { "Content-Type": "multipart/form-data" }
      });

      setTicketId(res.data.ticketId);

      // Reset form
      setForm({
        fullName: "",
        phone: "",
        category: "WHATSAPP",
        message: "",
        link: "",
        upiId: "",
        suspectNumber: ""
      });
      setScreenshot(null);
    } catch (err) {
      alert(err?.response?.data?.message || "Failed to submit case");
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="min-h-screen bg-gray-50">
      <Navbar />

      <div className="max-w-3xl mx-auto px-4 py-12">
        <h2 className="text-3xl font-black">Scam Check</h2>
        <p className="text-gray-600 mt-2">
          Submit link/message/UPI details. Our team will review and respond.
        </p>

        {ticketId && (
          <div className="mt-6 bg-green-50 border border-green-200 rounded-2xl p-4">
            ✅ Case submitted successfully. <br />
            <span className="font-bold">Ticket ID:</span> {ticketId}
          </div>
        )}

        <form
          onSubmit={submit}
          className="mt-8 bg-white rounded-3xl shadow p-6 space-y-4"
        >
          <div className="grid md:grid-cols-2 gap-4">
            <input
              className="border rounded-2xl px-4 py-3"
              placeholder="Full Name"
              value={form.fullName}
              onChange={(e) => setForm({ ...form, fullName: e.target.value })}
              required
            />

            <input
              className="border rounded-2xl px-4 py-3"
              placeholder="Phone Number"
              value={form.phone}
              onChange={(e) => setForm({ ...form, phone: e.target.value })}
              required
            />
          </div>

          <select
            className="border rounded-2xl px-4 py-3 w-full"
            value={form.category}
            onChange={(e) => setForm({ ...form, category: e.target.value })}
          >
            <option value="UPI">UPI</option>
            <option value="WHATSAPP">WhatsApp</option>
            <option value="INSTAGRAM">Instagram</option>
            <option value="SMS">SMS</option>
            <option value="CALL">Call</option>
            <option value="OTHER">Other</option>
          </select>

          <textarea
            className="border rounded-2xl px-4 py-3 w-full min-h-[120px]"
            placeholder="Paste the message or explain what happened..."
            value={form.message}
            onChange={(e) => setForm({ ...form, message: e.target.value })}
            required
          />

          <input
            className="border rounded-2xl px-4 py-3 w-full"
            placeholder="Suspicious Link (optional)"
            value={form.link}
            onChange={(e) => setForm({ ...form, link: e.target.value })}
          />

          <div className="grid md:grid-cols-2 gap-4">
            <input
              className="border rounded-2xl px-4 py-3"
              placeholder="UPI ID (optional)"
              value={form.upiId}
              onChange={(e) => setForm({ ...form, upiId: e.target.value })}
            />

            <input
              className="border rounded-2xl px-4 py-3"
              placeholder="Suspect Phone Number (optional)"
              value={form.suspectNumber}
              onChange={(e) =>
                setForm({ ...form, suspectNumber: e.target.value })
              }
            />
          </div>

          <div>
            <label className="text-sm font-semibold">
              Upload Screenshot (optional)
            </label>

            <input
              type="file"
              accept="image/*"
              className="mt-2"
              onChange={(e) => setScreenshot(e.target.files?.[0] || null)}
            />

            <div className="text-xs text-gray-500 mt-1">
              Max 2MB (png/jpg/webp)
            </div>
          </div>

          <button
            disabled={loading}
            className="w-full px-5 py-3 rounded-2xl bg-gray-900 text-white font-semibold disabled:opacity-60"
          >
            {loading ? "Submitting..." : "Submit for Scam Check"}
          </button>

          <div className="text-xs text-gray-600">
            🔒 CyberRaksha never asks for OTP/password and we do not take remote
            access.
          </div>
        </form>
      </div>
    </div>
  );
}
